const [first, second] = nodes.filter(node => node.tag === \"select\");
const [notes] = nodes.filter(node => node.tag === \"input\");
const output = nodes.find(node => node.tag === \"textarea\");
const copy = nodes.find(node => node.tag === \"button\");
